mapper.select:
SELECT id, message_id, conversation_id, sender_id, content, message_type,
       parent_message_id, metadata_json, is_edited, edited_at,
       created_at, updated_at, deleted_at, delete_flag
FROM messages
WHERE message_id = #{messageId}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

SELECT id, message_id, conversation_id, sender_id, content, message_type,
       parent_message_id, metadata_json, is_edited, edited_at,
       created_at, updated_at, deleted_at, delete_flag
FROM messages
WHERE conversation_id = #{conversationId}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}


    AND (
        created_at < #{lastCreatedAt}
        OR (created_at = #{lastCreatedAt} AND id < #{lastId})
    )


ORDER BY created_at DESC, id DESC
LIMIT #{limit}

SELECT COUNT(*)
FROM messages
WHERE conversation_id = #{conversationId}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

  AND id > COALESCE(#{lastReadMessageId}, 0)
